    ::fidl::WireResult<::fuchsia_io::Symlink::DeprecatedSetAttr>
    DeprecatedSetAttr(::fuchsia_io::wire::NodeAttributeFlags flags, const ::fuchsia_io::wire::NodeAttributes& attributes);

