// Pure-virtual interface to be implemented by a server.
// This interface uses typed channels (i.e. |::fidl::ClientEnd<::fuchsia_io::Symlink>|
// and |::fidl::ServerEnd<::fuchsia_io::Symlink>|).
template<>
class ::fidl::WireServer<::fuchsia_io::Symlink> : public ::fidl::internal::IncomingMessageDispatcher, public ::fidl::UnknownMethodHandler<::fuchsia_io::Symlink> {
  public:
  WireServer() = default;
  virtual ~WireServer() = default;

  // The FIDL protocol type that is implemented by this server.
  using _EnclosingProtocol = ::fuchsia_io::Symlink;

  using Handler = fidl::ProtocolHandler<::fuchsia_io::Symlink>;

    using LinkIntoCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::LinkInto>;
      using LinkIntoRequestView = ::fuchsia_io::wire::LinkableLinkIntoRequest*;

/// Creates a link to this this object with name `dst` in the directory represented by
/// `dst_parent_token`.
///
/// `dst` must be a resolved object name. Including "/" in the string will return
/// `ZX_ERR_INVALID_ARGS`.
///
/// This method requires the maximal set of rights supported by the filesystem for this object.
/// For files this would typically be [`Rights.READ_BYTES`], [`Rights.WRITE_BYTES`],
/// [`Rights.GET_ATTRIBUTES`] and [`Rights.UPDATE_ATTRIBUTES`]. Some filesystems might also
/// support the [`Rights.EXECUTE`] right. Insufficient rights will result in
/// `ZX_ERR_ACCESS_DENIED`.
///
/// If this object has no links and is *NOT* an unnamed temporary object (objects opened with
/// `Flags.FLAG_CREATE_AS_UNNAMED_TEMPORARY`), it will fail with `ZX_ERR_NOT_FOUND`.
///
/// For unnamed temporary objects, use LinkInto to give it a name. Upon successful completion,
/// the object will be permanently linked to the filesystem. Requires that the unnamed temporary
/// object is linkable, if not, it will fail with `ZX_ERR_NOT_FOUND`.
///
/// This method does not have the same atomicity properties has the `Directory::Link` method,
/// which means that calling `Open` then `LinkInto` is not equivalent to `Directory::Link`
/// because `LinkInto` will not prevent the source from being renamed or unlinked.
  virtual void LinkInto(
      ::fuchsia_io::wire::LinkableLinkIntoRequest* request,
    LinkIntoCompleter::Sync& completer) = 0;

    using CloneCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::Clone>;
      using CloneRequestView = ::fuchsia_unknown::wire::CloneableCloneRequest*;

  virtual void Clone(
      ::fuchsia_unknown::wire::CloneableCloneRequest* request,
    CloneCompleter::Sync& completer) = 0;

    using CloseCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::Close>;

/// Terminates the connection.
///
/// After calling `Close`, the client must not send any other requests.
///
/// Servers, after sending the status response, should close the connection
/// regardless of status and without sending an epitaph.
///
/// Closing the client end of the channel should be semantically equivalent
/// to calling `Close` without knowing when the close has completed or its
/// status.
  virtual void Close(
    CloseCompleter::Sync& completer) = 0;

    using QueryCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::Query>;

  virtual void Query(
    QueryCompleter::Sync& completer) = 0;

    using DeprecatedCloneCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::DeprecatedClone>;
      using DeprecatedCloneRequestView = ::fuchsia_io::wire::NodeDeprecatedCloneRequest*;

/// DEPRECATED - Use `fuchsia.unknown/Cloneable.Clone` instead.
  virtual void DeprecatedClone(
      ::fuchsia_io::wire::NodeDeprecatedCloneRequest* request,
    DeprecatedCloneCompleter::Sync& completer) = 0;

    using DeprecatedGetAttrCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::DeprecatedGetAttr>;

/// DEPRECATED - Use `Node.GetAttributes` instead.
///
/// This method requires the [`Rights.GET_ATTRIBUTES`] right.
  virtual void DeprecatedGetAttr(
    DeprecatedGetAttrCompleter::Sync& completer) = 0;

    using DeprecatedSetAttrCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::DeprecatedSetAttr>;
      using DeprecatedSetAttrRequestView = ::fuchsia_io::wire::NodeDeprecatedSetAttrRequest*;

/// DEPRECATED - Use `Node.UpdateAttributes` instead.
  virtual void DeprecatedSetAttr(
      ::fuchsia_io::wire::NodeDeprecatedSetAttrRequest* request,
    DeprecatedSetAttrCompleter::Sync& completer) = 0;

    using DeprecatedGetFlagsCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::DeprecatedGetFlags>;

/// [DEPRECATED - Use new GetFlags method instead.]
  virtual void DeprecatedGetFlags(
    DeprecatedGetFlagsCompleter::Sync& completer) = 0;

    using DeprecatedSetFlagsCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::DeprecatedSetFlags>;
      using DeprecatedSetFlagsRequestView = ::fuchsia_io::wire::NodeDeprecatedSetFlagsRequest*;

/// [DEPRECATED - Use new SetFlags method instead.]
  virtual void DeprecatedSetFlags(
      ::fuchsia_io::wire::NodeDeprecatedSetFlagsRequest* request,
    DeprecatedSetFlagsCompleter::Sync& completer) = 0;

    using GetFlagsCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::GetFlags>;

/// Queries the flags that apply to this node after it has been opened/created. This method does
/// not require any rights.
///
/// Note that the final set of flags that apply to the connection may differ from those
/// specified with the `fuchsia.io/Directory.Open` request used to create it:
///  - `Flags.PERM_INHERIT_*`: Only applies when determining connection rights.
///  - `Flags.PROTOCOL_*`: Only the protocol of the connection will be present.
///  - `Flags.FLAG_*`: Only applies when opening the resource, not part of the connection.
  virtual void GetFlags(
    GetFlagsCompleter::Sync& completer) = 0;

    using SetFlagsCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::SetFlags>;
      using SetFlagsRequestView = ::fuchsia_io::wire::NodeSetFlagsRequest*;

/// Sets the flags that apply to this node after it has been opened. This method does not
/// require any rights.
///
/// Only `Flags.FILE_APPEND` is currently supported. Calling this method without any flags will
/// clear append mode.
///
/// Errors:
///  - `ZX_ERR_NOT_SUPPORTED`: The object does not support this feature or the specified flags.
///  - `ZX_ERR_INVALID_ARGS`: `flags` other than `Flags.FILE_APPEND` were specified.
  virtual void SetFlags(
      ::fuchsia_io::wire::NodeSetFlagsRequest* request,
    SetFlagsCompleter::Sync& completer) = 0;

    using QueryFilesystemCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::QueryFilesystem>;

/// Query the filesystem for details specific to the filesystem and/or volume. If the current
/// volume has different settings or the storage is accounted seperately from the rest of the
/// filesystem that may be reported instead of filesystem-wide details.
  virtual void QueryFilesystem(
    QueryFilesystemCompleter::Sync& completer) = 0;

    using GetAttributesCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::GetAttributes>;
      using GetAttributesRequestView = ::fuchsia_io::wire::NodeGetAttributesRequest*;

/// Acquires information about the node.
///
/// The attributes of a node should be stable, independent of the
/// specific protocol used to access it.
///
/// If a particular attribute is not applicable or not supported,
/// filesystems should leave the corresponding field absent.
///
/// + `query` a bit-mask specifying which attributes to fetch. The server
///   should not return more than necessary.
/// - `attributes` the returned attributes.
///
/// This method requires the [`Rights.GET_ATTRIBUTES`] right.
  virtual void GetAttributes(
      ::fuchsia_io::wire::NodeGetAttributesRequest* request,
    GetAttributesCompleter::Sync& completer) = 0;

    using UpdateAttributesCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::UpdateAttributes>;
      using UpdateAttributesRequestView = ::fuchsia_io::wire::MutableNodeAttributes*;

/// Updates information about the node.
///
/// + `attributes` the presence of a table field in `attributes` indicates
/// the intent to update the corresponding attribute.
///
/// Returns `ZX_ERR_NOT_SUPPORTED` if the node does not support any of the specified attributes.
///
/// This method requires the [`Rights.UPDATE_ATTRIBUTES`] right.
  virtual void UpdateAttributes(
      ::fuchsia_io::wire::MutableNodeAttributes* request,
    UpdateAttributesCompleter::Sync& completer) = 0;

    using SyncCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::Sync>;

/// Synchronizes updates to the node to the underlying media, if it exists.
///
/// This method will return when the filesystem server has flushed the
/// relevant updates to the underlying media, but does not guarantee the
/// underlying media has persisted the information, nor that any information
/// is committed to hardware. Clients may use `Sync` to ensure ordering
/// between operations.
///
/// This method does not require any rights.
  virtual void Sync(
    SyncCompleter::Sync& completer) = 0;

    using ListExtendedAttributesCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::ListExtendedAttributes>;
      using ListExtendedAttributesRequestView = ::fuchsia_io::wire::NodeListExtendedAttributesRequest*;

/// Creates an iterator over all the extended attribute names associated
/// with this node. If an error occurs it is returned as an epitaph on the
/// iterator request channel, and then the channel is closed.
///
/// GetExtendedAttributes can be used with any of these names to retrieve
/// the associated value.
///
/// This method requires the [`Rights.READ_BYTES`] right.
  virtual void ListExtendedAttributes(
      ::fuchsia_io::wire::NodeListExtendedAttributesRequest* request,
    ListExtendedAttributesCompleter::Sync& completer) = 0;

    using GetExtendedAttributeCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::GetExtendedAttribute>;
      using GetExtendedAttributeRequestView = ::fuchsia_io::wire::NodeGetExtendedAttributeRequest*;

/// Get the value associated with the given attribute `name` for this node.
///
/// Attribute names have a maximum length of MAX_ATTRIBUTE_NAME. No
/// particular structure is imposed on them.
///
/// This method requires the [`Rights.READ_BYTES`] right.
  virtual void GetExtendedAttribute(
      ::fuchsia_io::wire::NodeGetExtendedAttributeRequest* request,
    GetExtendedAttributeCompleter::Sync& completer) = 0;

    using SetExtendedAttributeCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::SetExtendedAttribute>;
      using SetExtendedAttributeRequestView = ::fuchsia_io::wire::NodeSetExtendedAttributeRequest*;

/// Set the value for the given attribute `name` to `value` for this node.
///
/// The attribute name may exist, in which case the attribute is updated.
/// If the attribute doesn't exist, it is created. The name should have no
/// null bytes in it. If it does, ZX_ERR_INVALID_ARGS is returned.
///
/// This method requires the [`Rights.WRITE_BYTES`] right.
  virtual void SetExtendedAttribute(
      ::fuchsia_io::wire::NodeSetExtendedAttributeRequest* request,
    SetExtendedAttributeCompleter::Sync& completer) = 0;

    using RemoveExtendedAttributeCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::RemoveExtendedAttribute>;
      using RemoveExtendedAttributeRequestView = ::fuchsia_io::wire::NodeRemoveExtendedAttributeRequest*;

/// Remove the specified extended attribute.
///
/// If the attribute doesn't exist, ZX_ERR_NOT_FOUND is returned.
///
/// This method requires the [`Rights.WRITE_BYTES`] right.
  virtual void RemoveExtendedAttribute(
      ::fuchsia_io::wire::NodeRemoveExtendedAttributeRequest* request,
    RemoveExtendedAttributeCompleter::Sync& completer) = 0;

    using OpenCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::Open>;
      using OpenRequestView = ::fuchsia_io::wire::OpenableOpenRequest*;

/// Open (or create) a node relative to this directory. Any errors are communicated via an
/// epitaph sent on the `object` channel.
///
/// Errors:
/// * `ZX_ERR_BAD_PATH` if `path` is invalid
/// * See [`Flags`] for other errors which may be communicated based on `flags`
  virtual void Open(
      ::fuchsia_io::wire::OpenableOpenRequest* request,
    OpenCompleter::Sync& completer) = 0;

    using DescribeCompleter = ::fidl::internal::WireCompleter<::fuchsia_io::Symlink::Describe>;

  virtual void Describe(
    DescribeCompleter::Sync& completer) = 0;

  // |bind_handler| returns a handler that binds incoming connections to this
  // server implementation.
  //
  // The returned handler borrows the server instance.
  // The server must outlive the provided |dispatcher|. Only after
  // the dispatcher is shutdown will it be safe to destroy the servers.
  // The server should not be moved.
  Handler bind_handler(async_dispatcher_t* dispatcher);

  private:
  void dispatch_message(
    ::fidl::IncomingHeaderAndMessage&& msg, ::fidl::Transaction* txn,
    ::fidl::internal::MessageStorageViewBase* storage_view) final;
};

